(window.__quranSurahs=window.__quranSurahs||{})[99]={"nomPhon":"Az-Zalzala","versets":{"1":{"text":"Quand la terre tremblera d'un violent tremblement,","arabe":"إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا"},"2":{"text":"et que la terre fera sortir ses fardeaux,","arabe":"وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا"},"3":{"text":"et que l'homme dira: «Qu'a-t-elle?»","arabe":"وَقَالَ ٱلْإِنسَٰنُ مَا لَهَا"},"4":{"text":"ce jour-là, elle contera son histoire,","arabe":"يَوْمَئِذٍۢ تُحَدِّثُ أَخْبَارَهَا"},"5":{"text":"selon ce que ton Seigneur lui aura révélé [ordonné].","arabe":"بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا"},"6":{"text":"Ce jour-là, les gens sortiront séparément pour que leur soient montrées leurs œuvres.","arabe":"يَوْمَئِذٍۢ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًۭا لِّيُرَوْا۟ أَعْمَٰلَهُمْ"},"7":{"text":"Quiconque fait un bien fût-ce du poids d'un atome, le verra,","arabe":"فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ"},"8":{"text":"et quiconque fait un mal fût-ce du poids d'un atome, le verra.","arabe":"وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍۢ شَرًّۭا يَرَهُۥ"}}};